// INDIE PORT v0.23 — poster-safe editorial home + simplified social share
(()=>{
  const q=(s,p=document)=>p.querySelector(s);

  function installHeroPoster(){
    const hero=q("main#home > .hero"); if(!hero) return;
    hero.classList.add("hero-v23");
    if(q("#heroPosterPanel",hero)) return;
    const aside=document.createElement("aside");
    aside.id="heroPosterPanel";
    aside.className="hero-poster-panel";
    aside.innerHTML='<button class="hero-poster-frame" id="heroPosterOpen" type="button"><img id="heroPoster" alt=""></button>'+
      '<div class="hero-poster-meta"><span>NEXT SCREENING</span><b id="heroPosterTitle">다음 상영작</b><small id="heroPosterTime">상영시간 확인 중</small></div>';
    const old=q(".stat-stack",hero);
    old?old.replaceWith(aside):hero.appendChild(aside);
  }

  const baseRenderHero=window.renderHero;
  window.renderHero=function(){
    if(typeof baseRenderHero==="function") baseRenderHero();
    installHeroPoster();
    try{
      const first=typeof nextGlobalSession==="function"?nextGlobalSession():null;
      if(!first) return;
      const m=typeof movieFor==="function"?movieFor(first.code,first.title):null;
      if(!m) return;
      const poster=q("#heroPoster"), title=q("#heroPosterTitle"), time=q("#heroPosterTime"), open=q("#heroPosterOpen"), backdrop=q("#heroBackdrop");
      if(poster){ poster.src=m.poster||""; poster.alt=m.poster?((m.title||first.title)+" 포스터"):"포스터 없음"; poster.hidden=!m.poster; }
      if(title) title.textContent=m.title||first.title||"다음 상영작";
      if(time) time.textContent=(typeof fmtDate==="function"?fmtDate(first.date):first.date)+" "+first.start+" · "+(first.minutes||"")+"분";
      if(open) open.onclick=()=>typeof openMovie==="function"&&openMovie(first.code,first.title);
      const still=m.still||(Array.isArray(m.stills)&&m.stills[0])||"";
      const bg=still||m.poster||"";
      if(backdrop){
        backdrop.style.backgroundImage=bg?'url("'+bg.replaceAll('"','%22')+'")':"none";
        backdrop.classList.toggle("poster-fallback",!still&&!!m.poster);
      }
    }catch(e){ console.warn("[v23 hero]",e); }
  };

  function moveAfter(node,anchor){
    if(!node||!anchor||node===anchor||node.previousElementSibling===anchor) return;
    anchor.insertAdjacentElement("afterend",node);
  }
  let reorderQueued=false;
  function reorderHome(){
    reorderQueued=false;
    const main=q("main#home"); if(!main) return;
    const hero=q(":scope > .hero",main);
    const discover=q("#discover",main), criticism=q("#criticism",main), newsroom=q("#newsroom",main);
    const daily=q("#daily",main), lens=q("#cinephileLens",main), schedule=q("#schedule",main), program=q("#program",main);
    const data=q(".data-strip",main)?.parentElement;
    let anchor=hero;
    if(discover&&anchor){moveAfter(discover,anchor);anchor=discover;}
    if(criticism&&anchor){moveAfter(criticism,anchor);anchor=criticism;}
    if(newsroom&&anchor){moveAfter(newsroom,anchor);anchor=newsroom;}
    if(daily&&anchor){moveAfter(daily,anchor);anchor=daily;}
    if(lens&&anchor){moveAfter(lens,anchor);anchor=lens;}
    if(schedule&&anchor){moveAfter(schedule,anchor);anchor=schedule;}
    if(data&&anchor){moveAfter(data,anchor);anchor=data;}
    if(program&&anchor) moveAfter(program,anchor);
  }
  function queueReorder(){
    if(reorderQueued)return; reorderQueued=true; requestAnimationFrame(reorderHome);
  }

  function simplifySharePanel(){
    const sheet=q("#sharePanelV05 .share-sheet.v05"); if(!sheet||sheet.dataset.v23Simplified==="1") return;
    sheet.dataset.v23Simplified="1";
    const titleLabel=q("#shareTitleV05")?.closest("label"), midLabel=q("#shareMidV05")?.closest("label"), reviewLabel=q("#shareTextV05")?.closest("label");
    if(titleLabel&&titleLabel.firstChild) titleLabel.firstChild.textContent="영화명";
    if(reviewLabel&&reviewLabel.firstChild) reviewLabel.firstChild.textContent="한줄평";
    const adv=document.createElement("details");
    adv.className="share-advanced-v23";
    adv.innerHTML='<summary>고급 편집</summary><div class="share-advanced-body-v23"></div>';
    const body=q(".share-advanced-body-v23",adv);
    const essential=document.createElement("div"); essential.className="share-essential-v23";
    const options=q(".share-options",sheet);
    if(options){
      const labels=[...options.querySelectorAll(":scope > label")];
      if(labels[0]) essential.appendChild(labels[0]);
      labels.slice(1).forEach(x=>body.appendChild(x));
      options.remove();
    }
    if(midLabel) body.prepend(midLabel);
    [q(".share-photo-order",sheet),q(".share-layout-row",sheet),q(".share-gesture-wrap",sheet),q(".share-free-editor",sheet),q(".share-text-tools",sheet)].filter(Boolean).forEach(x=>body.appendChild(x));
    const copy=q(".share-copy-editor",sheet), preview=q(".share-preview",sheet), actions=q(".share-actions",sheet);
    if(copy&&essential.children.length) copy.insertAdjacentElement("afterend",essential);
    if(preview) preview.insertAdjacentElement("afterend",adv); else if(actions) actions.insertAdjacentElement("beforebegin",adv);
  }

  const baseShare=window.openSharePanelV05;
  if(typeof baseShare==="function"){
    window.openSharePanelV05=function(...args){
      const out=baseShare(...args);
      requestAnimationFrame(simplifySharePanel);
      return out;
    };
  }

  function boot(){
    installHeroPoster();
    if(typeof window.renderHero==="function") window.renderHero();
    queueReorder();
    const main=q("main#home");
    if(main) new MutationObserver(queueReorder).observe(main,{childList:true});
    setTimeout(queueReorder,300); setTimeout(queueReorder,1000); setTimeout(queueReorder,2200);
  }
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",boot,{once:true}); else boot();
})();

/* INDIE PORT v0.23 — poster-safe editorial hierarchy */
.poster-wrap{background:#11110f!important}
.poster-wrap img,.sheet-poster,.session .thumb{width:100%!important;height:100%!important;object-fit:contain!important;object-position:center!important;background:#11110f!important}
.hero-v23{grid-template-columns:minmax(0,1fr) minmax(230px,310px)!important;gap:22px!important;align-items:stretch}
.hero-v23 .hero-card{position:relative;overflow:hidden;min-height:560px!important}
.hero-v23 .hero-backdrop{position:absolute;inset:0;background-position:center;background-size:cover;background-repeat:no-repeat;filter:brightness(.72) saturate(.9)}
.hero-v23 .hero-backdrop.poster-fallback{filter:blur(18px) brightness(.42) saturate(.75);transform:scale(1.08)}
.hero-v23 .hero-copy{z-index:2}
.hero-poster-panel{display:flex;flex-direction:column;justify-content:flex-end;border-top:1px solid #4a453d;border-bottom:1px solid #4a453d;padding:14px 0 18px}
.hero-poster-frame{display:block;width:100%;aspect-ratio:2/3;border:0;background:#0b0b0a;padding:0;overflow:hidden;cursor:pointer}
.hero-poster-frame img{display:block;width:100%;height:100%;object-fit:contain;object-position:center;background:#0b0b0a}
.hero-poster-meta{display:grid;gap:4px;padding-top:12px}
.hero-poster-meta span{color:#d8553f;font-size:9px;font-weight:900;letter-spacing:.16em}
.hero-poster-meta b{font-size:18px;line-height:1.2}
.hero-poster-meta small{color:#8f897e;font-size:10px}
#community>.feature:not(.main){display:none!important}
.data-strip{font-size:10px!important;opacity:.72}
.share-sheet.v05 .preset-row{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px!important;border:0!important;padding:0!important;margin:14px 0!important}
.share-sheet.v05 .preset-row button{position:relative;min-height:76px;border:1px solid #49453d!important;border-radius:0!important;background:#121210!important;color:#eee9df!important;text-align:left;padding:36px 10px 9px!important;font-size:10px!important;overflow:hidden}
.share-sheet.v05 .preset-row button:before{content:"";position:absolute;left:8px;right:8px;top:8px;height:20px;border:1px solid #5a5449;background:#e9e3d8}
.share-sheet.v05 .preset-row button[data-preset="cinema"]:before{background:linear-gradient(90deg,#2a2925 0 68%,#d8553f 68%)}
.share-sheet.v05 .preset-row button[data-preset="split"]:before{background:linear-gradient(90deg,#e9e3d8 0 50%,#191816 50%)}
.share-sheet.v05 .preset-row button[data-preset="gallery"]:before{background:#f3eee4;box-shadow:inset 0 0 0 5px #fff}
.share-sheet.v05 .preset-row button[data-preset="noir"]:before{background:linear-gradient(90deg,#080808,#666)}
.share-sheet.v05 .preset-row button[data-preset="classic"]:before{background:#ddd1bb;border-color:#7e2f27}
.share-sheet.v05 .preset-row button.on{border-color:#d8553f!important;box-shadow:inset 0 -3px 0 #d8553f}
.share-essential-v23{display:flex;gap:12px;align-items:center;border-top:1px solid #3d3931;border-bottom:1px solid #3d3931;padding:10px 0;margin:10px 0}
.share-essential-v23 label{margin:0!important;flex:1}
.share-advanced-v23{border-top:1px solid #4b463d;border-bottom:1px solid #4b463d;margin:14px 0}
.share-advanced-v23 summary{cursor:pointer;list-style:none;padding:13px 0;color:#aaa398;font-size:11px;font-weight:800;letter-spacing:.04em}
.share-advanced-v23 summary::-webkit-details-marker{display:none}
.share-advanced-v23 summary:after{content:"＋";float:right;color:#d8553f}
.share-advanced-v23[open] summary:after{content:"−"}
.share-advanced-body-v23{display:grid;gap:12px;padding:0 0 14px}
.share-sheet.v05 .share-preview{margin-top:14px!important}
.share-sheet.v05 .share-copy-editor{grid-template-columns:1fr!important}
.share-sheet.v05 .share-copy-editor textarea{min-height:96px}
@media(max-width:720px){
  .hero-v23{display:grid!important;grid-template-columns:1fr!important;gap:18px!important;padding-top:18px!important}
  .hero-poster-panel{order:0;border-top:0;padding-top:0}
  .hero-poster-frame{width:min(72vw,290px);margin:0 auto}
  .hero-poster-meta{text-align:center;padding:10px 16px 0}
  .hero-v23 .hero-card{order:1;min-height:0!important;background:transparent!important;border-bottom:0!important}
  .hero-v23 .hero-backdrop{display:none!important}
  .hero-v23 .hero-copy{position:static!important;width:auto!important;padding:0!important;background:none!important}
  .hero-v23 .hero-copy h1{font-size:clamp(38px,12vw,54px)!important;line-height:.94!important;margin:8px 0 13px!important}
  .hero-v23 .hero-copy p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;margin-bottom:14px}
  #posterGrid{display:flex!important;grid-template-columns:none!important;gap:14px!important;overflow-x:auto!important;scroll-snap-type:x mandatory;padding:0 14px 16px 0;scrollbar-width:none}
  #posterGrid::-webkit-scrollbar{display:none}
  #posterGrid .poster-card{flex:0 0 min(72vw,270px)!important;scroll-snap-align:start;min-width:0}
  #posterGrid .poster-wrap{aspect-ratio:2/3!important}
  #posterGrid .poster-copy h3{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:2.4em}
  #posterGrid .poster-copy p{display:none!important}
  .data-strip{display:none!important}
  .share-sheet.v05 .preset-row{grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .share-sheet.v05 .share-formats{overflow-x:auto;white-space:nowrap}
}

const targets=await (await fetch("http://127.0.0.1:9233/json")).json();
const page=targets.find(x=>x.type==="page"&&x.url.includes("127.0.0.1:8910"));if(!page)throw new Error("page target not found");
const ws=new WebSocket(page.webSocketDebuggerUrl);let seq=0;const pending=new Map(),exceptions=[];await new Promise((res,rej)=>{ws.onopen=res;ws.onerror=rej});
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result)}if(m.method==="Runtime.exceptionThrown")exceptions.push(m.params.exceptionDetails.text)};
function call(method,params={}){return new Promise((resolve,reject)=>{const id=++seq;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}))})}
async function ev(expression){const r=await call("Runtime.evaluate",{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.text);return r.result.value}
await call("Runtime.enable");await call("Page.enable");await call("Page.reload",{ignoreCache:true});await new Promise(r=>setTimeout(r,2400));
for(let n=0;n<25;n++){if(await ev("!!document.getElementById('criticism')&&!!document.getElementById('newsroom')&&!!document.getElementById('heroPosterPanel')"))break;await new Promise(r=>setTimeout(r,250))}
await call("Emulation.setDeviceMetricsOverride",{width:390,height:844,deviceScaleFactor:1,mobile:true});await new Promise(r=>setTimeout(r,400));
const out={};out.order=await ev("[...document.querySelectorAll('main > section')].map(x=>x.id).filter(Boolean)");
out.posterFit=await ev("getComputedStyle(document.querySelector('#posterGrid .poster-wrap img')).objectFit");
out.posterRail=await ev("({display:getComputedStyle(document.getElementById('posterGrid')).display,overflow:getComputedStyle(document.getElementById('posterGrid')).overflowX})");
out.hero=await ev("({panel:!!document.getElementById('heroPosterPanel'),fit:getComputedStyle(document.getElementById('heroPoster')).objectFit,stats:!!document.querySelector('.stat-stack'),backdrop:getComputedStyle(document.getElementById('heroBackdrop')).display})");
await ev("openSharePanelV05(Object.keys(MOVIES)[0]);true");await new Promise(r=>setTimeout(r,250));
out.share=await ev("({presets:document.querySelectorAll('#presetRow [data-preset]').length,advanced:!!document.querySelector('.share-advanced-v23'),midInside:!!document.querySelector('.share-advanced-v23 #shareMidV05')})");
out.exceptions=exceptions;console.log(JSON.stringify(out,null,2));ws.close();
